using System;using System.IO;using System.Linq;using System.Windows.Forms;using System.Diagnostics;using System.Threading.Tasks;
namespace FocusGrowth {
static class ContinuousProgram {
 [STAThread]static int Main(string[] args){string root=AppDomain.CurrentDomain.BaseDirectory;try{
  if(args.Length==1&&args[0]=="--selftest"){Tests.Run(root);ContinuousTests.Run(root);return Environment.ExitCode;}
  bool synthetic=args.Length==1&&args[0]=="--synthetic-v04";
  Schema.Require(synthetic||args.Length==0||args.Length==1&&args[0]=="--production-readonly"||args.Length==2&&args[0]=="--authorize-production","invalid_mode");
  Application.EnableVisualStyles();string folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"FocusGrowthSync",synthetic?"v04-synthetic":"v04-production");var disk=new Disk(folder);var config=disk.Load("workspace");if(config==null){config=J.Obj(J.Parse("{}"));config["device"]=Guid.NewGuid().ToString("N");config["testId"]=Guid.NewGuid().ToString("N");disk.Save("workspace",config);}string device=(string)config["device"],remotePath=synthetic?"sync/tests/v04-"+device+".json":"sync/state.json";
  var grant=new ContinuousGrant(folder,device);var vault=new LocalVault(Path.Combine(folder,"backups"));
  if(args.Length==2){Authorize(args[1],disk,grant);return 0;}
  ContinuousController controller=null;using(var cloud=new ContinuousCloud(remotePath,!synthetic,()=>controller!=null&&controller.Enabled&&controller.Authorized)){
   controller=new ContinuousController(!synthetic,device,cloud,disk,vault,()=>grant.Valid);if(synthetic)controller.NetworkControl=offline=>cloud.TestOffline=offline;
   using(var form=new Form{Text="Focus & Growth V0.4 — "+(synthetic?"SYNTHETIC":"PRODUCTION READ-ONLY until separately authorized"),Width=920,Height=380,StartPosition=FormStartPosition.CenterScreen}){
    var pairing=new Pairing();var notice=new Label{Left=18,Top=12,Width=870,Height=66,Text=synthetic?"ISOLATED VIRTUAL DATA ONLY. Test transport offline mode does not change Windows networking.\nAuto-poll: 5 seconds. Pairing code is NOT a GitHub token.":"PRODUCTION: continuous writes are DISABLED without separate explicit authorization.\nPairing permits local encrypted backup and read-only verification. No Token enters the webpage."};
    var code=new TextBox{Left=18,Top=82,Width=620,ReadOnly=true,Text=pairing.Code};var rotate=new Button{Left=660,Top=80,Width=220,Text="New pairing code (pauses)"};rotate.Click+=(s,e)=>{controller.Release();pairing.Rotate();code.Text=pairing.Code;};
    var open=new Button{Left=18,Top=125,Width=300,Text="Open reviewed Pages workspace"};open.Click+=(s,e)=>Process.Start("https://tang0709.github.io/focus-growth/"+(synthetic?"?syncTest=1":""));
    var enable=new Button{Left=335,Top=125,Width=180,Text="Enable / Resume"};enable.Click+=async(s,e)=>{try{enable.Enabled=false;await Task.Run(()=>controller.ResumeCurrent());}catch(Fault ex){MessageBox.Show(form,ex.Code+"\nProduction requires a later explicit authorization and the separate native grant dialog.");}finally{enable.Enabled=true;}};
    var pause=new Button{Left=530,Top=125,Width=170,Text="Pause"};pause.Click+=async(s,e)=>{pause.Enabled=false;await Task.Run(()=>controller.Pause());pause.Enabled=true;};
    var stop=new Button{Left=715,Top=125,Width=165,Text="Stop"};stop.Click+=(s,e)=>form.Close();var status=new Label{Left=18,Top=180,Width=870,Height=135,Text="Starting paused. Existing queues and backups are preserved."};form.Controls.AddRange(new Control[]{notice,code,rotate,open,enable,pause,stop,status});
    using(var bridge=new ContinuousBridge(controller,pairing,Path.Combine(root,"web"),origin=>(bool)form.Invoke(new Func<bool>(()=>MessageBox.Show(form,"Pair "+origin+" with "+(synthetic?"ISOLATED SYNTHETIC":"PRODUCTION READ-ONLY")+" workspace?\nThis is not permission for production writes. Session lasts15 minutes.","Confirm V0.4 pairing",MessageBoxButtons.YesNo,MessageBoxIcon.Question,MessageBoxDefaultButton.Button2)==DialogResult.Yes))))
    using(var poll=new System.Threading.Timer(_=>controller.Tick(false),null,0,5000))using(var ui=new System.Windows.Forms.Timer{Interval=1000}){bool pending=false;ui.Tick+=async(s,e)=>{if(pending)return;pending=true;try{var v=await Task.Run(()=>controller.View());if(!form.IsDisposed)status.Text="Mode: "+v["mode"]+" | Enabled: "+v["enabled"]+" | Authorized: "+v["authorized"]+"\n"+v["status"]+" | "+v["error"]+"\nLast success: "+v["lastSuccess"]+"\n"+(synthetic?remotePath:"Only protocol project/task/plan fields may be synchronized; local private data stays local.");}finally{pending=false;}};bridge.Start();ui.Start();Application.Run(form);controller.Pause();}
   }
  }return 0;
 }catch(Fault ex){MessageBox.Show("Stopped safely: "+ex.Code);return 1;}catch{MessageBox.Show("V0.4 could not start. Check port, Windows user and local files. No secrets logged.");return 1;}}
 static void Authorize(string manifest,Disk disk,ContinuousGrant grant){
  var m=J.Obj(LocalJson.Parse(File.ReadAllText(manifest)));Schema.Require(m.Count==4&&m.ContainsKey("consentReference")&&m.ContainsKey("expectedRemoteSha")&&m.ContainsKey("expectedProjectionDigest")&&m.ContainsKey("expectedBackupSha256"),"explicit_scoped_consent_manifest_required");var attach=disk.Load("attach");Schema.Require(attach!=null,"read_only_pair_and_backup_first");var backup=J.Obj(attach["backup"]);Schema.Require((string)backup["sha256"]==(string)m["expectedBackupSha256"],"backup_changed");byte[] data=LocalVault.Read(backup);var db=J.Obj(LocalJson.Parse(System.Text.Encoding.UTF8.GetString(data)));PreparationModel.ValidateFull(db);var projected=PreparationModel.Project(db);Schema.Require(LocalJson.Digest(projected)==(string)m["expectedProjectionDigest"],"local_snapshot_changed");
  using(var cloud=new Cloud("sync/state.json",true)){cloud.Verify();var remote=cloud.Read(null);Schema.Require(remote.Sha==(string)m["expectedRemoteSha"]&&(bool)remote.State["initialized"]&&Schema.SameData(projected,remote.State),"read_only_baseline_mismatch");
   using(var f=new Form{Text="Separate explicit authorization — PRODUCTION continuous writes",Width=820,Height=330,StartPosition=FormStartPosition.CenterScreen}){var text=new Label{Left=18,Top=18,Width=770,Height=130,Text="ONLY after a new explicit user approval.\nScope: private tang0709/focus-growth-data / sync/state.json, projects/tasks/plans allowed fields.\nFuture local and remote task changes will be processed. No activity, timers, notes, theme or PAT exposure.\nValid7 days for this Windows installation; starts paused; pause/resume remains explicit.\nRemoteSHA: "+remote.Sha};var checkbox=new CheckBox{Left=18,Top=155,Width=770,Height=45,Text="I explicitly authorize this device to continuously synchronize the stated production fields."};var button=new Button{Left=18,Top=215,Width=350,Text="Grant scoped authorization (remain paused)",Enabled=false};checkbox.CheckedChanged+=(s,e)=>button.Enabled=checkbox.Checked;button.Click+=(s,e)=>{try{cloud.Verify();Schema.Require(cloud.Read(null).Sha==remote.Sha,"remote_changed");grant.Issue((string)m["consentReference"],remote.Sha,(string)backup["sha256"]);f.Close();}catch(Fault ex){MessageBox.Show(f,ex.Code);}};f.Controls.AddRange(new Control[]{text,checkbox,button});f.ShowDialog();}
  }Array.Clear(data,0,data.Length);
 }
}
